#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "msxresident_hash.h"

typedef struct { uint32_t h[8]; uint64_t n; unsigned char b[64]; size_t used; } SHA256;
static const uint32_t K[64] = { 0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2 };
static uint32_t r(uint32_t x,unsigned n){return(x>>n)|(x<<(32-n));}
static void block(SHA256*s,const unsigned char*p){uint32_t w[64],a,b,c,d,e,f,g,h,t1,t2;int i;for(i=0;i<16;i++)w[i]=((uint32_t)p[4*i]<<24)|((uint32_t)p[4*i+1]<<16)|((uint32_t)p[4*i+2]<<8)|p[4*i+3];for(;i<64;i++)w[i]=(r(w[i-15],7)^r(w[i-15],18)^(w[i-15]>>3))+w[i-16]+(r(w[i-2],17)^r(w[i-2],19)^(w[i-2]>>10))+w[i-7];a=s->h[0];b=s->h[1];c=s->h[2];d=s->h[3];e=s->h[4];f=s->h[5];g=s->h[6];h=s->h[7];for(i=0;i<64;i++){t1=h+(r(e,6)^r(e,11)^r(e,25))+((e&f)^((~e)&g))+K[i]+w[i];t2=(r(a,2)^r(a,13)^r(a,22))+((a&b)^(a&c)^(b&c));h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;}s->h[0]+=a;s->h[1]+=b;s->h[2]+=c;s->h[3]+=d;s->h[4]+=e;s->h[5]+=f;s->h[6]+=g;s->h[7]+=h;}
static void init(SHA256*s){static const uint32_t x[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};memset(s,0,sizeof(*s));memcpy(s->h,x,sizeof(x));}
static void add(SHA256*s,const void*v,size_t n){const unsigned char*p=v;s->n+=(uint64_t)n;while(n){size_t z=64-s->used;if(z>n)z=n;memcpy(s->b+s->used,p,z);s->used+=z;p+=z;n-=z;if(s->used==64){block(s,s->b);s->used=0;}}}
static void done(SHA256*s,unsigned char o[32]){uint64_t bits=s->n*8;int i;unsigned char z=0x80;add(s,&z,1);z=0;while(s->used!=56)add(s,&z,1);for(i=7;i>=0;i--){z=(unsigned char)(bits>>(i*8));add(s,&z,1);}for(i=0;i<8;i++){o[4*i]=(unsigned char)(s->h[i]>>24);o[4*i+1]=(unsigned char)(s->h[i]>>16);o[4*i+2]=(unsigned char)(s->h[i]>>8);o[4*i+3]=(unsigned char)s->h[i];}}
static void hex(const unsigned char*d,char o[65]){static const char x[]="0123456789abcdef";int i;for(i=0;i<32;i++){o[2*i]=x[d[i]>>4];o[2*i+1]=x[d[i]&15];}o[64]=0;}
int MSXresident_sha256File(const char *path,char o[65]){FILE*f;SHA256 s;unsigned char b[4096],d[32];size_t n;if(!path||!o)return 0;f=fopen(path,"rb");if(!f)return 0;init(&s);while((n=fread(b,1,sizeof(b),f))!=0)add(&s,b,n);if(ferror(f)){fclose(f);return 0;}fclose(f);done(&s,d);hex(d,o);return 1;}
int MSXresident_caseHashFiles(const char *inp,const char *msx,char o[65]){char a[65],b[65],x[130];SHA256 s;unsigned char d[32];if(!o||!MSXresident_sha256File(inp,a)||!MSXresident_sha256File(msx,b))return 0;memcpy(x,a,64);x[64]=':';memcpy(x+65,b,65);init(&s);add(&s,x,129);done(&s,d);hex(d,o);return 1;}
